function wl(string $k):string{global $labels,$usageMap;return $labels[$k]??($usageMap[$k]??$k);}function wv(mixed $v):string{return is_array($v)?json_encode($v,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT):(string)$v;}
