if($step!=='review'&&$action==='next'){$r=$w['records'][$step]??[];foreach((array)($_POST['technical']??[]) as $k=>$v){$txt=trim((string)$v);if(in_array($k,$arrays,true)){$d=json_decode($txt,true);$r[$k]=(json_last_error()===JSON_ERROR_NONE&&is_array($d))?array_values($d):$imp->split($txt);}else$r[$k]=$txt;}$r['asset_no']=trim((string)($_POST['asset_no']??''));$r['location']=trim((string)($_POST['location']??''));$r['personnel_id']=trim((string)($_POST['personnel_id']??''));if(!preg_match('/^\d{7}$/',$r['asset_no']))$err='شماره اموال باید دقیقاً ۷ رقم باشد.';elseif($r['location']==='')$err='مکان الزامی است.';else{$q=db()->prepare('SELECT asset_no FROM assets WHERE asset_no=?');$q->execute([$r['asset_no']]);if($q->fetchColumn())$err='شماره اموال '.$r['asset_no'].' قبلاً ثبت شده است. <a href="asset_edit.php?asset_no='.rawurlencode($r['asset_no']).'">ویرایش همین شماره اموال</a>';else{$w['records'][$step]=$r;$_SESSION['_hardware_wizard']=$w;$i=array_search($step,$steps,true);redirect($i<count($steps)-1?'asset_wizard.php?step='.$steps[$i+1]:'asset_wizard.php?step=review');}}}
if($step==='review'&&$action==='finish'){if(count(array_intersect($steps,array_keys($w['records'])))<4)$err='ابتدا هر چهار مرحله را تکمیل کنید.';else try{$seen=[];foreach($steps as $s){$no=$w['records'][$s]['asset_no']??'';if(!preg_match('/^\d{7}$/',$no))throw new RuntimeException('شماره اموال '.$types[$s].' نامعتبر است.');if(isset($seen[$no]))throw new RuntimeException('شماره اموال '.$no.' در مراحل تکرار شده است.');$seen[$no]=1;$q=db()->prepare('SELECT asset_no FROM assets WHERE asset_no=?');$q->execute([$no]);if($q->fetchColumn())throw new RuntimeException('شماره اموال '.$no.' قبلاً ثبت شده است؛ <a href="asset_edit.php?asset_no='.rawurlencode($no).'">ویرایش</a>');}db()->beginTransaction();foreach($steps as $s){$r=$w['records'][$s];$tech=[];foreach($r as $k=>$v)if($k[0]!=='_'&&!isset($usageMap[$k])&&!in_array($k,['asset_no','location','personnel_id'],true))$tech[$k]=$v;if($s==='computer')foreach(['IPAddresses','MACAddresses','SubnetMasks','Gateways','DNSServers','MonitorDetails'] as $drop)unset($tech[$drop]);if($s==='display'&&isset($w['records']['display']['MonitorDetails']))$tech['MonitorDetails']=$w['records']['display']['MonitorDetails'];$hostname=$r['ComputerName']??$r['PrinterName']??$r['ScannerName']??$r['DisplayName']??null;$manufacturer=$r['Manufacturer']??$r['PrinterManufacturer']??$r['ScannerManufacturer']??$r['DisplayManufacturer']??'';$model=$r['Model']??$r['PrinterModel']??$r['ScannerModel']??$r['DisplayModel']??'';$serial=$r['SystemSerial']??$r['PrinterSerial']??$r['ScannerSerial']??$r['DisplaySerial']??'';$q=db()->prepare('INSERT INTO assets(asset_no,asset_type,device_subtype,hostname,personnel_id,location,manufacturer,model,serial_no,technical,status,source_file,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$r['asset_no'],$s,$r['device_subtype']??null,$hostname,($r['personnel_id']??'')!==''?(int)$r['personnel_id']:null,$r['location'],$manufacturer,$model,$serial,json_encode($tech,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE),'active',$r['_source_file']??null,user()['id'],user()['id']]);if($s==='computer'){$u=[];foreach($usageMap as $src=>$col)$u[$col]=(($r[$src]??'')==='')?null:$r[$src];$q=db()->prepare('INSERT INTO usage_stats(asset_no,boot_count,normal_shutdown_count,unexpected_shutdown_count,user_shutdown_count,last_boot_time,last_shutdown_time,completed_session_count,current_session_hours,current_session_duration,total_usage_hours,total_usage_duration,average_session_hours,average_session_duration,longest_session_hours,longest_session_duration,collected_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE boot_count=VALUES(boot_count),normal_shutdown_count=VALUES(normal_shutdown_count),unexpected_shutdown_count=VALUES(unexpected_shutdown_count),user_shutdown_count=VALUES(user_shutdown_count),last_boot_time=VALUES(last_boot_time),last_shutdown_time=VALUES(last_shutdown_time),completed_session_count=VALUES(completed_session_count),current_session_hours=VALUES(current_session_hours),current_session_duration=VALUES(current_session_duration),total_usage_hours=VALUES(total_usage_hours),total_usage_duration=VALUES(total_usage_duration),average_session_hours=VALUES(average_session_hours),average_session_duration=VALUES(average_session_duration),longest_session_hours=VALUES(longest_session_hours),longest_session_duration=VALUES(longest_session_duration),collected_at=VALUES(collected_at)');$q->execute([$r['asset_no'],$u['boot_count'],$u['normal_shutdown_count'],$u['unexpected_shutdown_count'],$u['user_shutdown_count'],$u['last_boot_time'],$u['last_shutdown_time'],$u['completed_session_count'],$u['current_session_hours'],$u['current_session_duration'],$u['total_usage_hours'],$u['total_usage_duration'],$u['average_session_hours'],$u['average_session_duration'],$u['longest_session_hours'],$u['longest_session_duration'],$u['collected_at']]);}foreach($imp->disks($r) as $d)$q=db()->prepare('INSERT INTO asset_disks(asset_no,disk_index,model,size_gb,serial_no,interface_name,media) VALUES(?,?,?,?,?,?,?)')->execute([$r['asset_no'],$d['index'],$d['model'],$d['size_gb'],$d['serial_no'],$d['interface']??null,$d['media']??null]);foreach($imp->ramSlots($r) as $x)$q=db()->prepare('INSERT INTO asset_ram_slots(asset_no,slot_no,state,capacity_gb,ram_type,speed_mhz,manufacturer,part_number,serial_no) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$r['asset_no'],$x['slot_no'],$x['state']??'unknown',$x['capacity_gb']??null,$x['ram_type']??null,$x['speed_mhz']??null,$x['manufacturer']??null,$x['part_number']??null,$x['serial_no']??null]);audit('hardware_wizard_asset_created','asset',$r['asset_no'],['type'=>$s,'source'=>$r['_source_file']??null]);}db()->commit();unset($_SESSION['_hardware_wizard']);flash('success','هر چهار پایگاه با موفقیت ثبت شدند.');redirect('index.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}}
}
