?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ثبت مرحله‌ای تجهیزات</title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">HWiNFO · پایش سخت‌افزار</a><nav><a href="index.php">داشبورد</a><a href="assets.php">تجهیزات</a><a href="report.php">گزارش‌ها</a><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><div class="eyebrow">ثبت یکپارچه چهار پایگاه</div><h1><?=$step==='review'?'تأیید نهایی':'تحلیل '.$types[$step]?></h1><p class="muted">کامپیوتر، چاپگر، اسکنر و نمایشگر به‌صورت مرحله‌ای بررسی و سپس یکجا ثبت می‌شوند.</p></div></div><div class="wizard-steps"><?php foreach($steps as $s):?><a class="wizard-step <?=isset($w['records'][$s])?'done':''?> <?=$step===$s?'active':''?>" href="asset_wizard.php?step=<?=$s?>"><b><?=array_search($s,$steps)+1?></b><span><?=$types[$s]?></span></a><?php endforeach;?><a class="wizard-step <?=$step==='review'?'active':''?>" href="asset_wizard.php?step=review"><b>✓</b><span>تأیید نهایی</span></a></div><?php if($err):?><div class="alert danger"><?= $err ?></div><?php endif;?><?php if($step==='review'):?><section class="review-grid"><?php foreach($steps as $s):$x=$w['records'][$s]??[];?><article class="panel review-card"><div class="section-title"><h2><?=$types[$s]?></h2><a class="btn small" href="asset_wizard.php?step=<?=$s?>">ویرایش</a></div><div class="review-fields"><div><span>شماره اموال</span><strong><?=e($x['asset_no']??'—')?></strong></div><div><span>مدل</span><strong><?=e($x['Model']??$x['PrinterModel']??$x['ScannerModel']??$x['DisplayModel']??'—')?></strong></div><div><span>مکان</span><strong><?=e($x['location']??'—')?></strong></div><div><span>فایل</span><strong><?=e($x['_source_file']??'—')?></strong></div></div></article><?php endforeach;?></section><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="step" value="review"><div class="actions sticky-confirm"><button class="btn primary" name="action" value="finish">✓ تأیید نهایی و ثبت همه</button><button class="btn" name="action" value="reset">شروع مجدد</button></div></form><?php else:$people=db()->query('SELECT id,full_name,personnel_code FROM personnel ORDER BY full_name LIMIT 5000')->fetchAll();?><section class="panel"><h2>۱. بارگذاری و تحلیل <?=$types[$step]?></h2><form method="post" enctype="multipart/form-data" class="upload-row"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="step" value="<?=$step?>"><input type="hidden" name="action" value="analyze"><input type="file" name="csv" accept=".csv,text/csv" required><button class="btn" type="submit">تحلیل CSV</button></form><?php if(isset($r['_source_file'])):?><p class="muted">فایل تحلیل‌شده: <?=e($r['_source_file'])?></p><?php endif;?></section><form method="post" id="wizard-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="step" value="<?=$step?>"><div class="panel"><h2>۲. مشخصات پایه</h2><div class="form-grid"><label>شماره اموال *<input id="asset-no" name="asset_no" value="<?=e($r['asset_no']??'')?>" inputmode="numeric" pattern="\d{7}" maxlength="7" required><div id="duplicate-check" class="duplicate-check"></div></label><label>مکان *<input name="location" value="<?=e($r['location']??'')?>" required></label><?php if($step==='computer'):?><label>کاربر اصلی / مسئول<select name="personnel_id"><option value="">انتخاب پرسنل</option><?php foreach($people as $p):?><option value="<?=$p['id']?>" <?=((string)($r['personnel_id']??'')===(string)$p['id'])?'selected':''?>><?=e($p['full_name'].' — '.($p['personnel_code']??''))?></option><?php endforeach;?></select></label><?php endif;?></div><h2>۳. فیلدهای اختصاصی</h2><div class="form-grid"><?php $keys=array_keys($r);foreach($keys as $k){if($k[0]==='_'||in_array($k,['asset_no','location','personnel_id','Manufacturer','Model','SystemSerial'],true)||isset($usageMap[$k])||($step==='computer'&&in_array($k,['IPAddresses','MACAddresses','SubnetMasks','Gateways','DNSServers','MonitorDetails'],true)))continue;$v=$r[$k];?><label><?=e(wl($k))?><textarea name="technical[<?=e($k)?>]" rows="3" <?=is_array($v)?'dir="ltr"':''?>><?=e(wv($v))?></textarea></label><?php }if($step==='display'&&isset($r['MonitorDetails'])):?><label>اطلاعات نمایشگر استخراج‌شده<textarea name="technical[MonitorDetails]" rows="4"><?=e(wv($r['MonitorDetails']))?></textarea></label><?php endif;?></div><?php if($step==='computer'):?><h2>۴. آمار استفاده</h2><div class="form-grid"><?php foreach($usageMap as $src=>$col):if(!array_key_exists($src,$r))continue;?><label><?=e(wl($src))?><input name="technical[<?=e($src)?>]" value="<?=e((string)$r[$src])?>"></label><?php endforeach;?></div><?php endif;?><div class="actions sticky-confirm"><button class="btn primary" id="next-button" name="action" value="next">ذخیره مرحله و ادامه</button><a class="btn" href="index.php">انصراف</a></div></div></form></main><script>const n=document.getElementById('asset-no'),box=document.getElementById('duplicate-check'),next=document.getElementById('next-button');let timer;async function checkAsset(){if(!n)return;const v=n.value.trim();box.classList.remove('show');box.textContent='';next.disabled=false;if(!/^\d{7}$/.test(v))return;try{const r=await fetch('asset_check.php?asset_no='+encodeURIComponent(v),{credentials:'same-origin'}),d=await r.json();if(d.duplicate){box.innerHTML='<span>⚠️ شماره اموال تکراری است.</span><a class="btn small" href="'+d.edit_url+'">ویرایش همان تجهیز</a>';box.classList.add('show');next.disabled=true;}}catch(e){}}n.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(checkAsset,250)});n.addEventListener('blur',checkAsset);</script></body></html>
